const progress=readProgress(storage),media=matchMedia('(prefers-reduced-motion:reduce)'),sound=createStorySound();let guided=true,audioOn=soundOn(),active=null,state={},view='waiting',clock=0,last=0,paused=false,filmTime=0,filmPhase=-1,raf=0,selected=null,drag=null,routeDrawing=false,ignoreClick=false;
const reduced=()=>progress.motion||media.matches;
const narrator=new MovieNarrator(()=>{if(view==='cinema'){paused=true;$('film-gate').hidden=false;$('pause-film').textContent='Resume movie';$('start-film').focus({preventScroll:true});}},on=>$('film-buddy').classList.toggle('speaking',on));
narrator.setEnabled(audioOn);$('film-buddy').innerHTML=robotPortrait;
$('brand').innerHTML=kittyLogo+'<span>astro kitty</span><span class="brand-star">✦</span>';$('buddy-icon').innerHTML=robotPortrait;$('science-summary').innerHTML='<span class="disclosure-arrow">▶</span>'+truthBadge('real');sound.setEnabled(audioOn);
function save(){try{storage.setItem(SAVE,JSON.stringify(progress));}catch{$('storage').textContent='This browser could not save progress. Your patches remain available during this visit.';}}
function speak(text){if(guided&&audioOn)void sharedVoice.play(text);}
function message(text,error=false){if(error){$('cheer').textContent='';$('stage').classList.remove('celebrating');}if(error&&!text.startsWith('Good try'))text='Good try! '+text+' Try again.';$('feedback').textContent=text;state.error=error?2.5:0;speak(text);}
function celebrate(text,complete=false){state.cheer=2.5;state.error=0;sound.unlock();sound.play('yay');$('cheer').textContent=['Yay!','Shabbash!','You did it!'][Math.floor(Math.random()*3)];$('stage').classList.remove('celebrating');void $('stage').offsetWidth;$('stage').classList.add('celebrating');message($('cheer').textContent+' '+text);if(complete){if(!progress.done.includes(active.id)){progress.done.push(active.id);save();}state.won=true;$('patch').textContent='✦ Patch earned';$('next').hidden=false;$('play-more').hidden=false;}}
function switchView(name){narrator.stop();sharedVoice.stop();$('film-gate').hidden=true;view=name;document.body.classList.toggle('film-mode',name==='cinema');for(const id of ['cinema','campus','lesson'])$(id).hidden=id!==name;last=0;paused=false;$('pause').textContent='Pause';$('pause').setAttribute('aria-pressed','false');sharedVoice.stop();sound.stopAll();}
function startFilm(){active=null;switchView('cinema');document.body.classList.add('film-mode');filmTime=0;filmPhase=-1;$('pause-film').textContent='Pause movie';window.scrollTo(0,0);}
function campus(){document.body.dataset.lab='campus';active=null;selected=null;switchView('campus');$('progress').textContent=`${progress.done.length} / 5 discovery patches`;$('lab-cards').innerHTML=LABS.map((l,i)=>`<button class="card" data-lab="${l.id}"><span class="glyph" aria-hidden="true">${l.icon}</span><span class="status">${progress.done.includes(l.id)?'✓':'0'+(i+1)}</span><strong>${l.name}</strong></button>`).join('');$('graduation').hidden=progress.done.length!==5;window.scrollTo(0,0);}
let rounds={};try{rounds=JSON.parse(storage.getItem('astro-kitty-rounds-v3')||'{}');}catch{}
function openLab(id){document.body.dataset.lab=id;active=LABS.find(l=>l.id===id);if(!active)return;switchView('lesson');const round=Number.isInteger(rounds[id])?rounds[id]:0;rounds[id]=round+1;try{storage.setItem('astro-kitty-rounds-v3',JSON.stringify(rounds));}catch{}const yard=makeYard(round),garden=makeGarden(round);state={round,yard,garden,airRound:AIR_ROUNDS[round%3],loaded:[],base:1+round%4,floats:1,weights:round%2?5:0,net:3,y:200,vy:0,steady:0,repaired:false,route:[0],rover:{...yard.nodes[0],angle:0},plants:[0,0,0],health:[.15,.15,.15],stock:{...garden.stock},pair:[null,null],world:'earth',air:true,prediction:null,dropTime:0,completedDrops:new Set(),water:0,power:false,split:false,reaction:0,routed:{oxygen:false,hydrogen:false},flows:[],busy:false,cheer:0,error:0,won:false,elapsed:0};selected=null;$('cheer').textContent='';$('title').textContent=active.name;$('stage').dataset.lab=active.id;$('tag').textContent='NATIONAL KITTY SPACE CENTER';$('room').textContent='Round '+(round+1);$('patch').textContent=progress.done.includes(id)?'✦ Patch earned':'';$('next').hidden=true;$('play-more').hidden=true;$('fact').textContent=active.fact;$('model').textContent='Game: simplified. '+active.model;$('source').href=active.url;$('stage').classList.remove('celebrating');$('lesson').classList.remove('room-enter');void $('lesson').offsetWidth;$('lesson').classList.add('room-enter');$('world').setAttribute('aria-label',active.name+' interactive scene; equivalent controls below');message(shortHint());$('fact').textContent=active.id==='chemistry'?state.airRound.science:active.fact;controls();targets();window.scrollTo(0,0);$('back').focus({preventScroll:true});}
function shortHint(){return{float:'Astronauts practise floating in pools. Balance Kitty, then fix the equipment.',rover:'Connect the dots. Collect the flags. Avoid the rocks.',garden:'Match each plant’s picture to its supply.',gravity:'Pick two objects. Guess which lands first.',chemistry:state.airRound.hint}[active.id];}
function button(action,label,extra=''){return `<button data-action="${action}" ${extra}>${label}</button>`;}
function choose(action,label,on){return button(action,label,`aria-pressed="${on}"`);}
function supply(id,symbol,label,count){return `<button class="supply ${selected===id?'chosen':''}" data-item="${id}" aria-pressed="${selected===id}" ${count===0?'disabled':''}><span aria-hidden="true">${symbol}</span>${label}${count!=null?' · '+count:''}</button>`;}
function controls(){if(!active)return;document.body.dataset.world=state.world||'earth';const expanded=$('controls').querySelector('details')?.open;const focus=document.activeElement?.dataset?.action;let html='';const s=state;
if(active.id==='float')html=`<div class="row"><label>Float packs: <output id="floats-val">${s.floats}</output><input data-range="floats" aria-label="Float packs" type="range" min="0" max="4" value="${s.floats}"></label><label>Weight packs: <output id="weights-val">${s.weights}</output><input data-range="weights" aria-label="Weight packs" type="range" min="0" max="6" value="${s.weights}"></label>${button('repair',['Fix antenna','Turn valve','Attach tool'][s.round%3],'class="go"')}</div>`;
if(active.id==='rover')html=`<div class="row">${button('drive','▶ Drive','class="go"')}${button('undo','↶ Undo')}${button('clear','↻ Clear')}</div><details class="extra-controls"><summary>Tap a dot instead</summary><div class="row">${s.yard.nodes.map((n,i)=>button('node:'+i,String(i+1)+(n.flag?' ⚑':''),`aria-label="Route point ${i+1}"`)).join('')}</div></details>`;
if(active.id==='garden')html=`<div class="plant-mobile-actions">${s.garden.plants.map((p,i)=>button('plant:'+i,`<span>${NEEDS[p.need].icon}</span><strong>${p.name}</strong><small>${s.plants[i]>=p.amount?'✓ Ready':NEEDS[p.need].hint}</small>`)).join('')}</div><div class="tray">${Object.entries(s.stock).map(([id,count])=>supply(id,NEEDS[id].icon,NEEDS[id].label,count)).join('')}</div><details class="extra-controls"><summary>Tap to place</summary><div class="row">${s.garden.plants.map((p,i)=>button('plant:'+i,(s.plants[i]>=p.amount?'✓ ':'')+p.name)).join('')}${button('reset','↻ Reset')}</div></details>`;
if(active.id==='gravity')html=`<div class="row gravity-environment">${choose('world:earth','🌍 Earth',s.world==='earth')}${choose('world:mars','🔴 Mars',s.world==='mars')}${choose('air:on','Air',s.air)}${choose('air:off','Vacuum: no air',!s.air)}</div><section class="gravity-picker" aria-labelledby="object-choice-heading"><h2 id="object-choice-heading">Choose objects</h2><div class="tray gravity-objects">${OBJECTS.map(o=>`<button class="supply ${selected===o.id?'chosen':''}" data-item="${o.id}" aria-pressed="${selected===o.id}" ${s.pair.includes(o.id)?'disabled':''}><span aria-hidden="true">${o.symbol}</span>${o.label}</button>`).join('')}</div><div class="row gravity-bays">${[0,1].map(i=>button('bay:'+i,(i?'B: ':'A: ')+(OBJECTS.find(o=>o.id===s.pair[i])?.label||'Choose'),`aria-label="Place selected object in bay ${i?'B':'A'}"`)).join('')}</div></section><div class="row prediction-row"><span>Who lands first?</span>${choose('predict:A','A',s.prediction==='A')}${choose('predict:together','Together',s.prediction==='together')}${choose('predict:B','B',s.prediction==='B')}</div><div class="gravity-drop-actions">${button('drop','↓ Drop','class="go"')}${button('empty','↻ Reset')}</div>`;
if(active.id==='chemistry'){const items={h2o:['💧','Water'],energy:['⚡','Power'],filter:['▥','CO₂ filter'],fan:['✺','Fan'],coil:['❄','Cold coil']};html=s.split?(s.airRound.id==='oxygen'?`<div class="tray">${supply('oxygen','O₂','Crew air',s.routed.oxygen?0:1)}${supply('hydrogen','H₂','Recovery',s.routed.hydrogen?0:1)}</div><details class="extra-controls"><summary>Tap to connect</summary><div class="row">${button('tank:crew','Crew')}${button('tank:recovery','Recovery')}</div></details>`:'<p class="hint">'+s.airRound.science+'</p>'):`<div class="tray">${s.airRound.inputs.map(id=>supply(id,items[id][0],items[id][1],s.loaded.includes(id)?0:1)).join('')}${button('react','▶ Start','class="go"')}</div><details class="extra-controls"><summary>Tap to connect</summary>${button('feed','Connect selected item')}</details>`;}
$('controls').dataset.lab=active.id;$('controls').innerHTML=html;if($('controls').querySelector('details'))$('controls').querySelector('details').open=!!expanded;if(s.busy||paused)$('controls').querySelectorAll('input,button').forEach(b=>b.disabled=true);if(focus)[...$('controls').querySelectorAll('[data-action]')].find(b=>b.dataset.action===focus)?.focus({preventScroll:true});}
function target(zone,x,y,w,h,label){return `<button class="scene-target ${selected?'drop-ready':''}" data-zone="${zone}" style="left:${x/11}%;top:${y/5.4}%;width:${w/11}%;height:${h/5.4}%" aria-label="${label}" ${state.busy||paused?'disabled':''}>${label}</button>`;}
function targets(){if(!active)return;let html='';if(active.id==='rover')html=state.yard.nodes.map((p,i)=>target('node:'+i,p.x,p.y,46,46,`Route point ${i+1}`)).join('');if(active.id==='garden')html=[245,550,845].map((x,i)=>target('plant:'+i,x,305,190,285,state.garden.plants[i].name+': '+NEEDS[state.garden.plants[i].need].hint)).join('');if(active.id==='gravity')html=[385,715].map((x,i)=>target('bay:'+i,x,280,210,330,'Drop bay '+(i?'B':'A'))).join('')+OBJECTS.map((o,i)=>`<button class="scene-target pile-object" data-item="${o.id}" style="left:${(310+i*110)/11}%;top:${502/5.4}%;width:8%;height:10%" aria-label="Drag ${o.label} from the object pile" ${state.pair.includes(o.id)||state.busy||paused?'disabled':''}>${o.label}</button>`).join('');if(active.id==='chemistry')html=state.split?(state.airRound.id==='oxygen'?target('tank:crew',920,200,200,100,'Crew oxygen tank')+target('tank:recovery',920,355,200,100,'Hydrogen recovery tank'):''):target('feed',490,265,375,320,'Connect machine components');$('scene-targets').innerHTML=html;}
function addNode(i){if(state.route.at(-1)===i)return;if(i===0){state.route=[0];state.rover={...state.yard.nodes[0],angle:0};}else if(!state.route.includes(i))state.route.push(i);controls();}
function apply(zone,item=selected){const s=state;if(s.busy||paused)return;const[k,v]=zone.split(':');if(k==='node'){addNode(Number(v));return;}if(!item){message('Choose a supply first, then place it here.');return;}if(k==='plant'){const i=Number(v),r=tendPlant(s.garden,s.plants,s.stock,i,item);if(!r.ok){message(r.why,true);return;}s.pour={index:i,item,age:0,previous:s.health[i]};s.busy=true;selected=null;message({water:'A drink for dry roots.',lamp:'Light helps leaves make food.',nutrient:'Minerals help the plant grow.',fan:'Cool air helps this hot plant.',drain:'Extra water drains away. Roots can get air.'}[item]);controls();targets();}
if(k==='bay'){if(!OBJECTS.some(o=>o.id===item)||s.pair.includes(item)){message('Choose a different object for the other bay.');return;}s.pair[Number(v)]=item;selected=null;s.dropTime=0;s.prediction=null;controls();targets();message('Ready? Make your guess.');}
if(k==='feed'){if(!s.airRound.inputs.includes(item)){message('This machine needs a different item.',true);return;}if(s.loaded.includes(item))return;s.loaded.push(item);s.delivery={item,age:0};if(item==='h2o')s.water=2;if(item==='energy'||item==='fan')s.power=true;selected=null;sound.click();message(s.loaded.length===2?'Ready! Press Start.':'One more connection.');controls();}
if(k==='tank'){const right=item==='oxygen'&&v==='crew'||item==='hydrogen'&&v==='recovery';if(!right){message('Oxygen goes to the crew. Hydrogen goes to recovery.',true);return;}if(s.routed[item])return;s.routed[item]=true;s.flows.push({gas:item,age:0});selected=null;celebrate(item==='oxygen'?'Oxygen is flowing to the crew.':'Hydrogen is safely separated for recovery.',s.routed.oxygen&&s.routed.hydrogen);controls();targets();}}
function act(action){const s=state;if(!active||s.busy||paused)return;const[k,v]=action.split(':');if(['plant','bay','tank','feed','node'].includes(k)){apply(action);return;}if(k==='predict'){s.prediction=v;controls();return;}if(k==='world'){s.world=v;s.dropTime=0;s.prediction=null;controls();return;}if(k==='air'){s.air=v==='on';s.dropTime=0;s.prediction=null;controls();return;}if(action==='repair'){if(s.net||s.steady<1){message('Match the arrows and let Kitty settle.',true);return;}s.busy=true;s.repairTime=0;message('Steady paws! Kitty is fixing the equipment.');}
if(action==='drive'){if(s.route.length<2){message('Draw a route from dot 1 first.');return;}s.run=checkYard(s.yard,s.route);s.collected=[];s.driveAge=0;s.distance=0;s.segment=0;s.segmentProgress=0;s.busy=true;s.rover={...s.yard.nodes[0],angle:0};message('Let’s follow your route.');}
if(action==='undo'){if(s.route.length>1)s.route.pop();}if(action==='clear'){s.route=[0];s.rover={...s.yard.nodes[0],angle:0};}if(action==='reset'){s.plants=[0,0,0];s.health=[.15,.15,.15];s.stock={...s.garden.stock};selected=null;message(shortHint());}if(action==='empty'){s.pair=[null,null];s.dropTime=0;s.prediction=null;selected=null;}
if(action==='drop'){if(s.pair.some(x=>!x)){message('Place one object in each bay.');return;}if(!s.prediction){message('Choose your prediction before the drop.');return;}s.dropTime=0;s.landTimes=[null,null];s.busy=true;message('Same height. Same release time. Watch the landing order.');}
if(action==='react'){if(s.loaded.length<2){message('Connect both items first.');return;}s.busy=true;s.reaction=0;message({oxygen:'Water is splitting into two gases.',scrub:'Watch the CO₂ dots get trapped.',water:'Watch the water drops collect.'}[s.airRound.id]);}
controls();targets();}
$('controls').addEventListener('input',e=>{if(state.busy||paused)return;const key=e.target.dataset.range;if(key){state[key]=Number(e.target.value);state.steady=0;$(key+'-val').textContent=state[key];}});
$('controls').addEventListener('click',e=>{if(ignoreClick)return;const b=e.target.closest('button');if(!b||state.busy||paused)return;sound.unlock();if(b.dataset.item){selected=b.dataset.item;controls();targets();}else if(b.dataset.action)act(b.dataset.action);});
$('scene-targets').addEventListener('click',e=>{if(ignoreClick)return;const item=e.target.closest('[data-item]');if(item&&!item.disabled){selected=item.dataset.item;controls();targets();return;}const b=e.target.closest('[data-zone]');if(b)apply(b.dataset.zone);});
function point(e){const r=$('world').getBoundingClientRect();return{x:(e.clientX-r.left)*1100/r.width,y:(e.clientY-r.top)*540/r.height,inside:e.clientX>=r.left&&e.clientX<=r.right&&e.clientY>=r.top&&e.clientY<=r.bottom};}
function zoneAt(e){const p=point(e);if(!p.inside)return null;if(active.id==='garden'){const i=[245,550,845].findIndex(x=>Math.abs(p.x-x)<110&&p.y>150&&p.y<480);return i>=0?'plant:'+i:null;}if(active.id==='gravity'){const i=[385,715].findIndex(x=>Math.abs(p.x-x)<120&&p.y>90&&p.y<460);return i>=0?'bay:'+i:null;}if(active.id==='chemistry'){if(!state.split&&p.x>290&&p.x<690&&p.y>100&&p.y<440)return'feed';if(state.split&&p.x>810&&p.x<1030)return p.y<265?'tank:crew':'tank:recovery';}return null;}
document.addEventListener('pointerdown',e=>{const b=e.target.closest('[data-item]');if(!b||b.disabled||state.busy||paused)return;drag={item:b.dataset.item,label:b.textContent.trim(),x:e.clientX,y:e.clientY,moved:false};b.setPointerCapture(e.pointerId);});
$('stage').addEventListener('pointerdown',e=>{if(active?.id!=='rover'||state.busy||paused)return;const p=point(e),i=state.yard.nodes.findIndex(n=>Math.hypot(n.x-p.x,n.y-p.y)<35);if(i<0)return;e.preventDefault();routeDrawing=true;addNode(i);$('world').setPointerCapture(e.pointerId);});
document.addEventListener('pointermove',e=>{if(routeDrawing){const p=point(e),i=state.yard.nodes.findIndex(n=>Math.hypot(n.x-p.x,n.y-p.y)<32);if(i>=0)addNode(i);}if(drag){drag.moved ||= Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>6;if(drag.moved){const g=$('drag-ghost');g.hidden=false;g.textContent=drag.label;g.style.left=e.clientX+'px';g.style.top=e.clientY+'px';}}});
document.addEventListener('pointerup',e=>{if(routeDrawing){routeDrawing=false;ignoreClick=true;setTimeout(()=>ignoreClick=false,0);}if(drag){if(drag.moved){const zone=zoneAt(e);selected=drag.item;if(zone)apply(zone,drag.item);else message('Drop it onto a highlighted destination, or tap to place it.');ignoreClick=true;setTimeout(()=>ignoreClick=false,0);}drag=null;$('drag-ghost').hidden=true;}});
document.addEventListener('pointercancel',()=>{drag=null;routeDrawing=false;$('drag-ghost').hidden=true;});
function update(dt){clock+=dt;if(!active)return;const s=state;s.elapsed+=dt;if(s.delivery){s.delivery.age+=dt;if(s.delivery.age>1)s.delivery=null;}for(const f of s.flows)f.age+=dt;s.flows=s.flows.filter(f=>f.age<1.3);s.cheer=Math.max(0,s.cheer-dt);s.error=Math.max(0,s.error-dt);if(s.cheer===0){$('stage').classList.remove('celebrating');$('cheer').textContent='';}
if(active.id==='float'){s.net=s.base+s.floats-s.weights;s.vy+=(s.net*-22-s.vy*2.6)*dt;s.y=Math.max(175,Math.min(330,s.y+s.vy*dt));if(s.y===175||s.y===330)s.vy=0;s.steady=s.net===0&&Math.abs(s.vy)<5?s.steady+dt:0;if(s.busy){s.repairTime+=dt;if(s.repairTime>1.6){s.repaired=true;s.busy=false;celebrate('Balanced forces keep Kitty steady.',true);controls();targets();}}}
if(active.id==='rover'&&s.busy){const seg=s.run.segments[s.segment];if(!seg){s.busy=false;if(s.run.ok)celebrate('Both flags collected. Home safely!',true);else message(s.run.why,true);controls();targets();}else{s.driveAge+=dt;if(s.driveAge<.45)return;s.segmentProgress+=dt*175/Math.max(1,seg.len);const f=Math.min(seg.hit,easeInOut(s.segmentProgress)),angle=turnToward(s.rover.angle,Math.atan2(seg.b.y-seg.a.y,seg.b.x-seg.a.x),9,dt);s.distance+=dt*175;s.rover={x:seg.a.x+(seg.b.x-seg.a.x)*f,y:seg.a.y+(seg.b.y-seg.a.y)*f,angle};if(f>=seg.hit){if(seg.hit<1){s.busy=false;message(s.run.why,true);sound.thunk();controls();targets();}else{const flag=s.route[s.segment+1];if(s.yard.flags.includes(flag)&&!s.collected.includes(flag)){s.collected.push(flag);sound.click();}s.segment++;s.segmentProgress=0;}}}}
if(active.id==='garden'){for(let i=0;i<3;i++){const target=s.pour?.index===i&&s.pour.age<.7?s.pour.previous:.15+.85*state.plants[i]/s.garden.plants[i].amount;s.health[i]=damp(s.health[i],target,2.5,dt);}if(s.pour){s.pour.age+=dt;if(s.pour.age>2){s.pour=null;s.busy=false;celebrate(s.plants.every((n,i)=>n>=s.garden.plants[i].amount)?'Every plant feels better!':'Looking better. Help the next plant.',s.plants.every((n,i)=>n>=s.garden.plants[i].amount));controls();targets();}}}
if(active.id==='gravity'&&s.busy){s.dropTime+=dt;s.pair.forEach((o,i)=>{if(s.landTimes[i]===null&&dropDistance(s.dropTime,s.world,s.air,o)>=4)s.landTimes[i]=s.dropTime;});if(s.landTimes.every(n=>n!==null)){s.busy=false;const result=gravityResult(s.world,s.air,s.pair),reason=gravityReason(s.world,s.air,s.pair);if(s.prediction===result)celebrate(reason,true);else{message(reason,true);s.prediction=null;}controls();targets();}}
if(active.id==='chemistry'&&s.busy){s.reaction+=dt;if(s.reaction>3){s.busy=false;s.split=true;if(s.airRound.id==='oxygen')message('Oxygen to the crew. Hydrogen to recovery.');else celebrate(s.airRound.id==='scrub'?'The filter trapped CO₂. Cabin air is clearer.':'Water collected! It still needs cleaning before drinking.',true);controls();targets();}}
}
function readout(){const s=state;return{float:()=>s.busy?'Fixing the equipment…':s.net===0?'Balanced forces · '+(s.steady>1?'Ready to repair':'Settling…'):s.net>0?'Kitty is rising · Add weight to balance':'Kitty is sinking · Add floats to balance',rover:()=>s.busy?'Rover following your route…':'⚑ '+s.yard.flags.map(i=>i+1).join(' + ')+' → 8',garden:()=>s.pour?'Supplies arriving · Recovery sped up':`${Object.values(s.stock).reduce((a,b)=>a+b,0)} supplies left`,gravity:()=>`${s.world==='earth'?'Earth':'Mars'} · ${s.air?'Air':'Vacuum: no air'} · ${s.busy?'Falling…':'4 m drop'}`,chemistry:()=>s.busy?'Working…':s.airRound.name}[active.id]();}
const academyCaption=document.querySelector('.film-caption');
let frameSamples=[],renderSamples=[],lastMetrics=0;function frame(ts){const renderStart=performance.now();raf=0;if(document.hidden)return;const dt=frameDelta(last,ts),movieElapsed=last?Math.max(0,(ts-last)/1000):0;last=ts;if(!paused){update(dt);if(view==='cinema'){const boundary=ARRIVAL_CHAPTERS[Math.max(0,filmPhase)].end;filmTime=sharedVoice.busy?Math.min(boundary-.001,filmTime+movieElapsed):filmTime+movieElapsed;}}if(view==='cinema'){const i=drawFilm($('film'),filmTime,reduced());if(i!==filmPhase){filmPhase=i;$('film-tag').textContent='EARTH ACADEMY';$('film-title').textContent=ARRIVAL_CHAPTERS[i].title;$('film-line').textContent=ARRIVAL_CHAPTERS[i].line;void narrator.play(i);$('cinema').dataset.chapter=i;}academyCaption.style.setProperty('--scene-copy-opacity',filmCopyOpacity(filmTime-ARRIVAL_CHAPTERS[i].start,reduced()).toFixed(2));$('film-progress').textContent=`${Math.min(ARRIVAL_DURATION,Math.floor(filmTime))} / ${ARRIVAL_DURATION} seconds`;if(filmTime>=ARRIVAL_DURATION)campus();}if(view==='campus')drawHall($('hall-art'),clock,reduced());if(view==='lesson'&&active){drawLab($('world'),active.id,state,clock,reduced());const nextReadout=readout();if($('readout').textContent!==nextReadout)$('readout').textContent=nextReadout;}const elapsed=performance.now()-renderStart;renderSamples.push(elapsed);if(dt>0&&!paused)frameSamples.push(dt*1000);if(ts-lastMetrics>1200){const average=a=>a.reduce((x,y)=>x+y,0)/Math.max(1,a.length);$('world').dataset.renderMs=average(renderSamples).toFixed(2);$('world').dataset.frameMs=average(frameSamples).toFixed(2);renderSamples=[];frameSamples=[];lastMetrics=ts;}raf=requestAnimationFrame(frame);}
